L7_1.m_Pos = "L"
L7_1.m_Talk_KOREA = "여기가 G 스타디움이야. 꿈이 시작되는 곳이지."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "ここはGスタジアムだ。夢が始まるところさ。"
L7_1.m_Talk_ENG = "This is G Stadium. It's where you take your first step toward your dream."
L7_1.m_Talk_TWN = "這裡就是G體育場，是我們夢想的起點！"
L7_1.m_Talk_THA = "นี่คือ G สเตเดี้ยม เป็นที่ที่เธอเดินสู่ความฝันก้าวแรก"
L7_1.m_Talk_VTN = "Đây là sân vận động G. Đó là nơi cô thực hiện bước đầu tiên hướng tới ước mơ của mình."
L7_1.m_Talk_SCN = "这里就是G体育场了，也会是我们梦想开始的地方！"
L7_1.m_Talk_DEU = "Das ist das G-Stadion. Hier beginnen Träume."
L7_1.m_Talk_FRA = "C'est le Stade G. Là où les rêves commencent..."
