L9_1 = {}
L9_1.m_CutScenKey_Talk = "CHARADE_ACT4_STAGE1_START@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 5400402
L9_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "ADMIN_COFFIN_NULL_QM"
L9_1.m_Talk_KOREA = "이제까지 봤던 경기장과는 많이 다르군."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "これまで見てきた競技場とはだいぶ違うな。"
L9_1.m_Talk_ENG = "This is vastly different from the grounds we saw up until now."
L9_1.m_Talk_TWN = "和我之前看過的體育場很不一樣呢。"
L9_1.m_Talk_THA = "ที่นี่แตกต่างอย่างมากจากพื้นที่ที่เราเห็น"
L9_1.m_Talk_VTN = "Điều này rất khác so với những căn cứ mà chúng ta đã thấy cho đến bây giờ."
L9_1.m_Talk_SCN = "和我之前看过的体育场很不一样啊。"
L9_1.m_Talk_DEU = "Dieses Stadion unterscheidet sich erheblich von denen, die wir bisher gesehen haben."
L9_1.m_Talk_FRA = "C'est vraiment différent de ce qu'on a connu jusqu'à présent."
L10_1 = {}
L10_1.m_CutScenKey_Talk = "CHARADE_ACT4_STAGE1_START@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 5400402
L10_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
