L10_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L10_1.m_Pos = "R"
L10_1.m_Talk_KOREA = "라이카 말대로 여기서부터가 시작이거든요."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "ライカの言うとおり、ここからが始まりよ。"
L10_1.m_Talk_ENG = "Like Laika said, this is the first proper step."
L10_1.m_Talk_TWN = "就像萊卡說的那樣，這裡才是真正的開始。"
L10_1.m_Talk_THA = "อย่างที่ไลกาพูด นี่เป็นขั้นตอนแรก"
L10_1.m_Talk_VTN = "Như Laika đã nói, đây mới là bước đầu tiên."
L10_1.m_Talk_SCN = "因为就像莱卡说的那样，这里才是开始。"
L10_1.m_Talk_DEU = "Wie Laica gesagt hat: „Hier fängt alles an.“"
L10_1.m_Talk_FRA = "Comme l'a dit Leica, c'est là que tout commence."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "CHARADE_ACT4_STAGE1_START@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 5400402
L11_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L11_1.m_Pos = "R"
L11_1.m_Talk_KOREA = "본선은 예선과 포인트 최대치부터 달라요. 차원 함선도 기용하니까요."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "本戦は予選とポイントの最大値から異なるの。次元艦船も起用するから。"
L11_1.m_Talk_ENG = "The elimination round is nothing like the qualifiers. The maximum amount of points is increased, and they even dispatch dimensional ships."
L11_1.m_Talk_TWN = "決賽和預賽的點數上限不同，還可以使用次元艦船。"
L11_1.m_Talk_THA = "รอบคัดเลือกไม่เหมือนรอบคัดเลือกอื่น จำนวนคะแนนสูงสุดจะเพิ่มขึ้น และพวกเขายังส่งยานรบมิติมาอีกด้วย"
L11_1.m_Talk_VTN = "Vòng loại trực tiếp không giống như vòng trước. Số điểm tối đa được tăng lên và họ còn điều động các tàu không gian nữa."
L11_1.m_Talk_SCN = "淘汰赛和预选赛的点数上限不同，还可以使用次元舰船。"
L11_1.m_Talk_DEU = "Das Finale hat nichts mit der Qualifikationsrunde zu tun. Die maximale Punktzahl wird erhöht und es werden sogar Dimensionsschiffe entsandt."
L11_1.m_Talk_FRA = "Les éliminatoires n'ont rien à voir avec les qualifications. On a le droit d'utiliser plus de points, il y aura aussi des vaisseaux dimensionnels."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "CHARADE_ACT4_STAGE1_START@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 5400402
L12_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_LAUGH"
L12_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L12_1.m_Pos = "L"
L12_1.m_Talk_KOREA = "오디션 방송 같은 거 본 적 있어? 우린 이제 겨우 심사위원들 앞에 선 거야."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "オーディション番組とか見たことあるか？　私たちは、やっと審査委員の前に立ったんだ。"
L12_1.m_Talk_ENG = "Ever watched an audition before? Now we get to face the actual judges."
L12_1.m_Talk_TWN = "你看過選秀節目嗎？我們現在才算是真正站到評審面前。"
L12_1.m_Talk_THA = "นี่เคยเข้าร่วมการออดิชั่นมาก่อนหรือปล่าว? ตอนนี้เราจะได้เห็นผู้ตัดสินตัวจริงแล้ว "
L12_1.m_Talk_VTN = "Đã từng xem mấy show tài năng bao giờ chưa? Giờ thì chúng ta đã đối mặt với BGK thực sự."
L12_1.m_Talk_SCN = "你看过选秀节目吗？从这里开始才是通过海选站到评委前。"
L12_1.m_Talk_DEU = "Habt ihr schon einmal so etwas wie eine Casting-Sendung gesehen? Wir stehen gleich vor der Jury."
L12_1.m_Talk_FRA = "Tu as déjà regardé une audition auparavant ? Maintenant, nous allons devoir faire face à de vrais juges."
