L14_1.m_Crash = 15
L14_1.m_Talk_KOREA = "그, 그렇게 들으니까 단번에 와 닿네요…. 갑자기 긴장돼요."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "そ、そう聞くと一気に実感が湧きますね……急に緊張してきました。"
L14_1.m_Talk_ENG = "Th-that makes it sound too real... I'm getting anxious now."
L14_1.m_Talk_TWN = "聽，聽你這麼一說，一下子就有感覺咧……突然好緊張喔。"
L14_1.m_Talk_THA = "นั่นมันฟังดูเวอร์เกินไปปะ... ตอนนี้ทำให้ฉันกำลังวิตกกังวลอยู่นะ"
L14_1.m_Talk_VTN = "Cô nói thế đột nhiên thấy hơi không thật.. Giờ tôi đang bị lo lắng đây."
L14_1.m_Talk_SCN = "听、听你这么一说，一下子就有感觉了……突然好紧张啊。"
L14_1.m_Talk_DEU = "Langsam wird es ernst ... Ich bin jetzt total nervös."
L14_1.m_Talk_FRA = "T-Tout semble si réel tout à coup... Je commence à stresser."
