L16_1.m_Talk_KOREA = "저쪽이다! 어서 가서 찍어!"
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "あっちだ！　早く撮れ！"
L16_1.m_Talk_ENG = "There! Take her photo, now!"
L16_1.m_Talk_TWN = "在那邊！快點過去拍照！"
L16_1.m_Talk_THA = "นั้นไงเธอ! ถ่ายรูปเธอเร็ว!"
