L17_1 = {}
L17_1.m_CutScenKey_Talk = "CHARADE_ACT4_STAGE1_START@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 5400402
L17_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
