L17_1.m_CharStrID = "PHOTO_EXTRA_NULL_B"
L17_1.m_Talk_KOREA = "기자입니다! 잠시만 지나가겠습니다! 좀 비켜 주세요!"
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "記者です！　ちょっと通ります！　どいてください！"
L17_1.m_Talk_ENG = "Excuse me, coming through! I'm a reporter! Move aside, please!"
L17_1.m_Talk_TWN = "我是記者！借過！請讓讓！"
L17_1.m_Talk_THA = "ขอออัยนะครับ! ผมเป็นนักข่าว! โปรดหลีกทางเราหน่อย!"
L17_1.m_Talk_VTN = "Xin lỗi! Tôi là phóng viên! Vui lòng cho qua!"
L17_1.m_Talk_SCN = "我是记者！借过！请让让！"
L17_1.m_Talk_DEU = "Entschuldigung, ich muss mal durch! Ich bin ein Reporter! Gehen Sie bitte zur Seite!"
L17_1.m_Talk_FRA = "Excusez-moi ! Je suis journaliste ! Poussez-vous, s'il vous plaît !"
