L20_1.m_Pos = "L"
L20_1.m_Talk_KOREA = "갑자기 무슨 소란이야? 우리 찍으러 왔대?"
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "いきなり何の騒ぎなんだ？　私たちの撮影？"
L20_1.m_Talk_ENG = "What's going on? Are they here to take pictures of us?"
L20_1.m_Talk_TWN = "怎麼突然這麼熱鬧？是來拍我們的嗎？"
L20_1.m_Talk_THA = "เกิดอะไรขึ้น? นี่เขามาถ่ายรูปเราเหรอ?"
L20_1.m_Talk_VTN = "Sao tự nhiên náo nhiệt thế? Họ ở đây để chụp ảnh chúng ta à?"
L20_1.m_Talk_SCN = "怎么突然这么热闹？是来拍我们的吗？"
L20_1.m_Talk_DEU = "Was ist plötzlich los? Sind sie hier, um Fotos von uns zu machen?"
L20_1.m_Talk_FRA = "Qu'est-ce qu'il se passe ? Ils veulent prendre des photos de nous ?"
L21_1 = {}
L21_1.m_CutScenKey_Talk = "CHARADE_ACT4_STAGE1_START@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 5400402
L21_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L21_1.m_Pos = "R"
L21_1.m_Talk_KOREA = "저희는 안중에도 없어 보이던데요. 저쪽으로 다 몰려갔어요."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "私たちなど眼中にないみたいよ。みんなあっちに行ったもの。"
L21_1.m_Talk_ENG = "From the looks of it, they don't care who we are. They are all off towards that direction."
L21_1.m_Talk_TWN = "完全沒把我們看在眼裡呢，一窩蜂衝到那邊去了。"
L21_1.m_Talk_THA = "ดูจากท่าทางแล้วพวกเขาไม่สนใจหรอกว่าเราเป็นใคร พวกเขาทั้งหมดมุ่งไปทางนั้นมากกว่า"
L21_1.m_Talk_VTN = "Họ hoàn toàn không quan tâm chúng ta là ai. Tất cả đều đi về hướng đó."
L21_1.m_Talk_SCN = "完全没把我们看在眼里呢，一窝蜂冲到那边去了。"
L21_1.m_Talk_DEU = "So wie es aussieht, ist es ihnen egal, wer wir sind. Sie sind alle in diese Richtung unterwegs."
L21_1.m_Talk_FRA = "Je ne crois pas qu'ils sont intéressés par nous. Ils se dirigent par là-bas."
