L24_1.m_Bounce = L25_1
L24_1.m_Talk_KOREA = "어쩌면 유명인이 경기를 보러 왔는지도 몰라요! 구경하러 가요!"
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "もしかしたら、有名人が試合を見に来たのかもしれません！　行きましょう！"
L24_1.m_Talk_ENG = "Maybe someone famous has come to see the match! Let's go take a peek!"
L24_1.m_Talk_TWN = "說不定是有名人來看比賽！我們去看看吧！"
L24_1.m_Talk_THA = "อาจมีคนดังมาดูการแข่งขันนี้! ไปดูกัน!"
L24_1.m_Talk_VTN = "Chắc là có người nổi tiếng tới xem trận đấu! Chúng ta đi hóng tí nào!"
L24_1.m_Talk_SCN = "说不定是有名人来看比赛！我们去看看吧！"
L24_1.m_Talk_DEU = "Vielleicht ist jemand Berühmtes gekommen, um das Spiel zu sehen! Wir sollten uns das mal anschauen gehen!"
L24_1.m_Talk_FRA = "Peut-être que quelqu'un de célèbre est venu voir le match ! Allons voir !"
