L26_1.m_CharStrID = "MINA_FENRIR_CHIEF_NULL"
L26_1.m_Pos = "C_F_L"
L26_1.m_Talk_KOREA = "혹시 알파트릭스 회장님 아니야?"
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "ひょっとして、アルファトリックスの会長じゃない？"
L26_1.m_Talk_ENG = "Maybe it might be the President of Alphatrix?"
L26_1.m_Talk_TWN = "難道是阿爾法崔克斯會長？"
L26_1.m_Talk_THA = "ไม่แน่ นั่นอาจจะเป็นประธานของ อัลฟาทริกซ์ ก็ได้นะ?"
L26_1.m_Talk_VTN = "Hay đó là Chủ tịch của Alphatrix?"
L26_1.m_Talk_SCN = "难道是阿尔法崔克斯会长？"
L26_1.m_Talk_DEU = "Vielleicht ist es die Vorsitzende von Alphatrix?"
L26_1.m_Talk_FRA = "Peut-être la présidente d'Alphatrix ?"
