L28_1 = {}
L28_1.m_CutScenKey_Talk = "CHARADE_ACT4_STAGE1_START@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 5400402
L28_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "ADMIN_COFFIN_NULL_QM"
L28_1.m_Talk_KOREA = "여기까지 올 만큼 한가한 상황은 아닐 텐데…?"
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "ここまで来るほど、暇な状況ではないはずだが……？"
L28_1.m_Talk_ENG = "I don't think she's got time to come all this way..."
L28_1.m_Talk_TWN = "她應該沒閒到有時間來這裡吧……？"
L28_1.m_Talk_THA = "ผมไม่คิดว่าเธอจะมีเวลามาดู..."
L28_1.m_Talk_VTN = "Tôi không nghĩ cô ấy có thời gian để tới tận đây..."
L28_1.m_Talk_SCN = "她应该没闲到有时间来这里吧……？"
L28_1.m_Talk_DEU = "Ich glaube nicht, dass sie die Zeit hat, um hierherzukommen ..."
L28_1.m_Talk_FRA = "Je ne suis pas sûr qu'elle ait le temps pour ça..."
L29_1 = {}
L29_1.m_CutScenKey_Talk = "CHARADE_ACT4_STAGE1_START@29#Talk"
