L29_1.m_Crash = 20
L29_1.m_Talk_KOREA = "저기 보세요! 기자들이 잔뜩 몰려 있어요!"
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "あっちを見てください！　記者さんがいっぱいです！"
L29_1.m_Talk_ENG = "Look there! The reporters are all gathered over there!"
L29_1.m_Talk_TWN = "看那邊！記者都圍在那裡！"
L29_1.m_Talk_THA = "ดูนั่นสิ! นักข่าวมารวมตัวกันที่นั่น!"
L29_1.m_Talk_VTN = "Nhìn kia kìa! Các phóng viên đều tập trung ở đằng kia!"
L29_1.m_Talk_SCN = "看那边！记者都围在那儿呢！"
L29_1.m_Talk_DEU = "Schauen Sie mal dort! Die Reporter sind alle dort drüben versammelt!"
L29_1.m_Talk_FRA = "Regardez ! Les journalistes sont tous attroupés là-bas !"
