L36_1.m_fWaitTime = 0
L36_1.m_StartFXSoundName = "FX_CUTSCEN_CROWD_NOISE"
L37_1 = "PHOTO_EXTRA_NULL_C"
L36_1.m_CharStrID = L37_1
L37_1 = "스완 씨! 이번에 출연하시는 작품에 대해 한 말씀 부탁드립니다!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "スワンさん！　今度出演する作品について、一言お願いします！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Swan! Please tell us about your newest movie!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "史旺！請談談你這次演出的作品！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "สวอน! ภาพยนตร์ใหม่ล่าสุดของคุณเป็นยังไงบ้างคะ!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Cô Swan! Vui lòng chia sẻ một chút về bộ phim mới nhất của cô!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "斯旺小姐！请谈谈您这次出演的作品！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Swan! Bitte erzählen Sie uns von Ihrem neuesten Film!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Swan ! Parlez-nous de votre nouveau film !"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "CHARADE_ACT4_STAGE1_START@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 5400402
L37_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "PHOTO_EXTRA_NULL_D"
L37_1.m_CharStrID = L38_1
L38_1 = "최근 법정에 출두한 건틀렛 선수와의 열애설에 대해서 입장 표명해 주실 수 있나요!"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "最近法廷に出頭したガントレット選手との熱愛報道について、立場を表明してくれませんか！"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Do you have anything to say about the scandal between you and the Gauntlet player who was recently in court?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "大家都在傳你和最近出庭的聖鎧選手在戀愛中，你能說說你的立場嗎？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "คุณมีอะไรจะพูดเกี่ยวกับเรื่องอื้อฉาวระหว่างคุณกับผู้เล่นกอนต์เล็ตที่เพิ่งขึ้นศาลไปไหมครับ?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Cô có điều gì muốn nói về scandal với tuyển thủ Gauntlet vừa phải hầu tòa không?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "关于您和最近出庭的圣铠选手的恋爱传闻，您能说说您的立场吗？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Haben Sie etwas zu dem Skandal zwischen Ihnen und dem Fehde-Spieler zu sagen, der kürzlich vor Gericht stand?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Avez-vous quelque chose à dire au sujet du scandale entre vous et le joueur de la compétition qui a récemment comparu devant la cour ?"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "CHARADE_ACT4_STAGE1_START@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 5400402
L38_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "PHOTO_EXTRA_NULL_E"
L38_1.m_CharStrID = L39_1
L39_1 = "올해 여우주연상 시상식에 불참하셨는데, 무슨 이유였습니까!"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "今年の主演女優賞の授賞式には不参加でしたが、理由は何ですか！"
L38_1.m_Talk_JPN = L39_1
L39_1 = "You didn't attend the award ceremony for this year's leading female actress. Why was that?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "今年你沒出席最佳女主角的頒獎典禮，請問有什麼特別的原因嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ทำไมคุณไม่ได้ไปร่วมงานประกาศรางวัลดารานำหญิงของปีนี้ครับ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Cô đã không tham dự lễ trao giải cho nữ diễn viên xuất sắc năm nay. Tại sao vậy?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "今年您没出席最佳女主角的颁奖典礼，请问有什么特别的原因吗？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Sie waren nicht bei der Preisverleihung für die diesjährige Hauptdarstellerin dabei. Was war der Grund dafür?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Pourquoi n'avez-vous pas assisté à la cérémonie de l'artiste de l'année ?"
L38_1.m_Talk_FRA = L39_1
