L43_1 = "사, 사사, 사장님! 사진기! 엄청 큰 사진기가 필요해요!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "しゃ、しゃしゃ、社長！　カメラ！　めちゃくちゃ大きいカメラが必要です！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "B-B-B-Boss! Camera! I need a camera, a big one, now!"
