L45_1 = "네! 국제 영화상을 매년 전부 독점하는 바람에 수상 거부까지 한 전설이에요!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "はい！　国際映画賞を毎年全部独り占めしちゃうせいで、受賞拒否までしたっていう伝説の人なんですよ！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Yes! She's a living legend! She even refused to receive an award because she swept every award, in and out of the country every year!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "沒錯！史旺是傳奇人物欸！她每年都獨佔各大國際電影獎項而且還拒絕領獎！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ใช่ค่ะ! เธอคือตำนานของลีต! เธอถึงกับปฏิเสธที่จะรับรางวัลเพราะเธอกวาดทุกรางวัลทั้งในและต่างประเทศทุกปี!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Đúng! Cô ấy là một huyền thoại sống! Cô còn từ chối nhận thưởng vì năm nào cũng càn quét hết mọi giải thưởng trong và ngoài nước!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "没错！斯旺小姐是每年都独占各大国际电影奖项并且还拒绝领奖的传奇人物！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ja! Sie ist eine lebende Legende! Sie weigerte sich sogar, eine Auszeichnung entgegenzunehmen, weil sie jedes Jahr jede Auszeichnung im In- und Ausland abräumt!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Oui ! C'est une véritable légende vivante ! Elle a même refusé de recevoir un prix parce qu'elle les a tous raflés ! Des prix nationaux et internationaux !"
L44_1.m_Talk_FRA = L45_1
