L46_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L47_1 = "헤에, 의외로 코치도 세상 돌아가는 일에 관심 없구나?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "へえ、意外とコーチも世間話に興味ないんだな？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Huh, so you're not that much into mainstream media, Coach?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "哈，沒想到教練也不關注社會時事呢？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เธอไม่ค่อยอินกับสื่อในกระแสสักเท่าไหร่ นะโค้ช "
L46_1.m_Talk_THA = L47_1
L47_1 = "Hehe, vậy là ngài không quan tâm nhiều đến truyền thông chính thống nhỉ HLV?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "啊哈，真意外啊，教练也不关注时事吗？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Hehe, du stehst also nicht so sehr auf Mainstream-Medien, Trainer?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Tu n'es pas très people, boss, hein ?"
