L47_1.m_StartFXSoundName = L48_1
L47_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L48_1 = "본인 관심사가 아니면 신경 쓰지 않는 거겠죠."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "自分が興味ないことなら、気にしないだけでしょ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "He doesn't care about things that are not of his interest."
L47_1.m_Talk_ENG = L48_1
L48_1 = "應該是不在乎不感興趣的事吧？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เธอไม่สนใจสิ่งที่สนใจเธอ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Ngài ấy không quan tâm đến những thứ không phải là sở thích của mình."
L47_1.m_Talk_VTN = L48_1
L48_1 = "应该是不在乎不感兴趣的事吧。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Er kümmert sich nicht um Dinge, die ihn nicht interessieren."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Il ne se soucie pas des choses qui ne l'intéressent pas."
