L49_1 = "능력 있는 사람들은 그런 성격이 많대요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "能力のある人たちに、そんな性格が多いらしいわ。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "They say a lot of influential people are like that."
L48_1.m_Talk_ENG = L49_1
L49_1 = "據說很多有能力的人都是這樣的性格。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "พวกเขาพูดว่า ผู้มีอิทธิพลจำนวนมากเป็นแบบนี้เสมอ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Nghe nói nhiều người có sức ảnh hưởng đều như vậy."
L48_1.m_Talk_VTN = L49_1
L49_1 = "据说很多有能力的人都是这样的性格。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Man sagt, dass viele einflussreiche Menschen so sind."
L48_1.m_Talk_DEU = L49_1
L49_1 = "On dit que beaucoup de personnes influentes sont comme ça."
