L51_1 = "사장님, 저 사람이랑도 아는 사이야? 사장님을 보고 웃는데?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "社長、あの人とも知り合いなの？　社長を見て笑ってるけど。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Boss, do you know her? She's smiling at you."
L50_1.m_Talk_ENG = L51_1
L51_1 = "老闆，你認識那個人嗎？她剛才在朝老闆笑呢？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "บอส คุณรู้จักเธอหรอ นั่นเธอกำลังส่งยิ้มให้คุณน่ะ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Ông Chủ, ngài có quen cô ấy không? Cô ấy đang mỉm cười với ngài kìa."
L50_1.m_Talk_VTN = L51_1
L51_1 = "老板，你认识那个人吗？她刚才在朝老板笑呢？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Boss, kennst du sie etwa auch? Sie lächelt dich an."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Boss, tu la connais ? Elle te sourit."
L50_1.m_Talk_FRA = L51_1
