L2_1 = "설마. 오늘 처음 보는 사이라네."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "まさか。今日初めて会うんだが。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Of course not. This is the first time I've seen her."
L1_1.m_Talk_ENG = L2_1
L2_1 = "不會吧？我今天是第一次見到她。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "แน่นอน ไม่ นี่เป็นครั้งแรกที่ผมได้เห็นเธอ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Dĩ nhiên là không. Đây là lần đầu tiên tôi thấy cô ấy."
L1_1.m_Talk_VTN = L2_1
L2_1 = "怎么会，今天我是第一次见到她。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Natürlich nicht. Das ist das erste Mal, dass ich sie sehe."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Bien sûr que non. C'est la première fois que je la vois."
L1_1.m_Talk_FRA = L2_1
