L2_1[L3_1] = L4_1
L3_1 = "아무리 그래도 만나는 사람들마다 접점이 있진 않아."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "いくらなんでも、出会う人全員と関わりがあるわけではない。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Just because I have connections doesn't mean I know everyone."
L2_1.m_Talk_ENG = L3_1
L3_1 = "我的人脈沒有廣到跟每個人都有接觸。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "เพียงแค่เพราะผมมีคนรู้จัก นั่นก็ไม่ได้หมายความว่าผมรู้จักทุกคน"
L2_1.m_Talk_THA = L3_1
L3_1 = "Nói thế nào đi nữa thì không phải gặp ai tôi cũng quen biết được."
L2_1.m_Talk_VTN = L3_1
L3_1 = "哈哈，我也不是和每个见到的人都会有交集的。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Nur weil ich viele Kontakte habe, heißt das nicht, dass ich jeden kenne."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Ce n'est pas parce que j'ai des connexions que je connais tout le monde."
L2_1.m_Talk_FRA = L3_1
