L5_1.m_CharStrID = "PHOTO_EXTRA_NULL_A"
L6_1 = "스완 씨! 그 미소의 의미는 뭔가요? 방금 질문과 무슨 연관 있습니까?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "スワンさん！　今の笑顔の意味は何ですか？　さっきの質問と何か関係があるんですか？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Swan! Why are you smiling? Is it related to the question I asked?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "史旺！請問你剛才的微笑有什麼意思嗎？和剛才的問題有什麼關係嗎？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "คุณสวอนครับ! คุณยิ้มอะไรครับ? นั่นหมายถึงคำถามที่ผมถามคุณหรือปล่าว?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Swan! Tại sao cô lại cười? Nó có liên quan đến câu hỏi của tôi không?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "斯旺小姐！请问您刚才的微笑有什么含义？和刚才的问题有什么关系吗？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Swan! Warum lächeln Sie? Hängt es mit der Frage zusammen, die ich gerade gestellt habe?"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Swan ! Pourquoi est-ce que vous souriez ? C'est suite à ma question ?"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "CHARADE_ACT4_STAGE1_START@56#Talk"
