L6_1.m_CharStrID = "PHOTO_EXTRA_NULL_B"
L7_1 = "잠깐, 저기 있는 건 예선전 참가 팀 아니야?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "ちょっと、あそこにいるのって、予選の参加チームじゃないか？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Wait, aren't those people over there playing for the qualifiers?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "等等，那不是預賽的參賽隊伍嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "เดี๋ยวก่อน คนพวกนั้นเล่นรอบคัดเลือกไม่ใช่เหรอ?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Đợi đã, không phải những người đó chơi ở vòng đấu trước sao?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "等等，那边不是预选赛的参赛队伍吗？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Moment mal, sind das da drüben nicht Teilnehmer der Qualifikationsrunde?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Attendez, ceux-là participent aux qualifications, non ?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
