L8_1 = "PHOTO_EXTRA_NULL_C"
L7_1.m_CharStrID = L8_1
L8_1 = "거기 남성 분! 혹시 스완 씨와 무슨 관계십니까?!"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "そこの男性の方！　スワンさんとはどんな関係ですか！？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "You there, mister! What is your relationship with Swan?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "那邊那位先生！他和史旺有什麼關係嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "คุณคนนั้น! ความสัมพันธ์ของคุณกับคุณสวอนเป็นยังไง?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Anh chàng đó! Anh có quan hệ gì Swan sao?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "那边那位男士！和斯旺小姐有什么关系吗？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Hey, Sie da drüben! Welche Beziehung haben Sie zu Swan?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Vous, là-bas ! Quelle est votre relation avec Swan ?"
