L11_1 = 0.3
L9_1[L10_1] = L11_1
L10_1 = "사장님께 듣고 싶은 말이 많은 것 같은데요?! 둘러싸였다간 경기 전에 녹초가 되겠어요!"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "社長に聞きたいことがたくさんあるみたいですよ！？　囲まれたら試合の前でどっと疲れちゃいます！"
L9_1.m_Talk_JPN = L10_1
L10_1 = "They want to interview you, Boss! We'll get trampled even before the match starts!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "似乎是想要採訪老闆呢？！被包圍的話，比賽前就會被弄得筋疲力盡吧！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "พวกเขาต้องการจะสัมภาษณ์คุณ บอส! เราจะถูกกระทืบก่อนที่การแข่งขันจะเริ่มขึ้น!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Họ muốn phỏng vấn ngài, Ông Chủ! Chúng ta sẽ bị xô đẩy ngay cả trước khi trận đấu bắt đầu mất!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "好像是想要采访老板呢？！被围住的话，比赛之前都别想出来了！"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Sie wollen Sie interviewen, Boss! Wir werden schon vor Spielbeginn umzingelt!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Je crois bien qu'ils veulent vous interviewer, monsieur ! On va se faire piétiner avant même que le match commence !"
L9_1.m_Talk_FRA = L10_1
