L23_1 = "PHOTO_EXTRA_NULL_E"
L22_1.m_CharStrID = L23_1
L23_1 = "스완 씨, 오늘 경기를 보러 오신 이유가 뭐죠?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "スワンさん、今日の試合を見に来た理由は何ですか？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Swan, why did you come to see today's match?"
L22_1.m_Talk_ENG = L23_1
L23_1 = "史旺，你今天來看比賽的原因是什麼？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "คุณสวอนทำไมมาดูการแข่งขันนัดวันนี้?"
L22_1.m_Talk_THA = L23_1
L23_1 = "Swan, tại sao cô lại đến xem trận đấu hôm nay?"
L22_1.m_Talk_VTN = L23_1
L23_1 = "斯旺小姐，您今天来看比赛的原因是什么？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Swan, warum sind Sie gekommen, um sich das heutige Spiel anzusehen?"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Swan, pourquoi êtes-vous venue voir le match d'aujourd'hui ?"
