L24_1 = "PHOTO_EXTRA_NULL_F"
L23_1.m_CharStrID = L24_1
L24_1 = "후원하는 팀이라도 있는 건가요? 평소 건틀릿에 흥미가 있으셨나요?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "後援するチームでもあるんですか？　普段からガントレットに興味はあったんですか？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Is there a team you're rooting for? Were you always interested in the Gauntlet?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "是有你支持的隊伍嗎？你平時對聖鎧感興趣嗎？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "มีทีมที่คุณเชียร์อยู่หรือปล่าวครับ? คุณสนใจอะไรในกอนต์เล็ตหรือปล่าว?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Cô đang ủng hộ đội nào sao? Cô có luôn quan tâm đến Gauntlet không?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "是有您支持的队伍吗？您平时对圣铠感兴趣吗？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Gibt es ein Team, das Sie unterstützen? Haben Sie sich schon immer für die Fehde interessiert?"
L23_1.m_Talk_DEU = L24_1
