L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 5400402
L29_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_LAUGH"
L30_1 = "MITCH_NPC_NULL_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "C_R_M_I"
L29_1.m_Pos = L30_1
L30_1 = "예─이! 설마 티케팅 실패했다고 이불 속에서 질질 짜고 있는 거 아니지?"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "まったく！　まさかチケットをゲットできなかったからって、布団の中でシクシク泣いてるんじゃないよね？"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Eyyy! Hope no one's sobbing because they failed to get tickets for the match!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "哎—呀！大家不會因為搶票失利就躲在被子裡哭吧？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "เยย! หวังว่าจะไม่มีใครร้องไห้เพราะไม่ได้ตั๋วเข้ามาดูสำหรับการแข่งขันนี้นะ!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Êyyy! Hy vọng sẽ không ai phải nức nở vì không mua được vé xem trận đấu nhé!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "哎——呦！大家不会因为抢票失败而躲在被子里抹眼泪呢吧？"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Heyyy! Hoffentlich quetscht sich niemand heimlich unters Dach, nur weil er keine Karten für das Spiel bekommen hat!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Helloooo ! J'espère que personne ne pleurniche car il n'a pas son ticket !"
L29_1.m_Talk_FRA = L30_1
