L31_1 = "CHARADE_ACT4_STAGE1_START@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 5400402
L30_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_IDLE"
L31_1 = "MITCH_NPC_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "걱정 마시라! 이 건틀렛의 요정, 베티 미치가 현장에 나와 있으니까☆"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ご心配無用！　このガントレットの妖精、ベティー・ミッチーが現場に来てるから☆"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Don't you all worry! Your Gauntlet fairy, Batty Mitchie, is here on the scene for you! ☆"
L30_1.m_Talk_ENG = L31_1
L31_1 = "別擔心！聖鎧精靈，貝蒂·米奇就在現場☆！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ทุกคนไม่ต้องห่วง!  มิทชี่ นางฟ้ากอนต์เล็ตของคุณ มาอยู่ที่นี่เพื่อพวกคุณแล้ว! ☆"
L30_1.m_Talk_THA = L31_1
L31_1 = "Đừng lo! Nàng tiên Gauntlet Batty Mitchie đã có mặt tại đây rồi."
L30_1.m_Talk_VTN = L31_1
L31_1 = "别担心！因为圣铠精灵——贝蒂·米琪替大家来到现场了☆！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Keine Sorge! Denn die Fee der Fehde, Batty Mitchie, ist direkt am Ort des Geschehens! ☆"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Mais ne vous inquiétez pas ! Votre fée de la compétition est là☆"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "CHARADE_ACT4_STAGE1_START@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 5400402
L31_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "MITCH_NPC_NULL_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "R_F_C"
L31_1.m_Pos = L32_1
L32_1 = "이곳은 G 스타디움! 객석도 경기장도 뜨거운 열기로 후끈 달아오른 곳!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ここはGスタジアム！　客席も競技場も、アツアツの熱気で熱く燃え上がってるところ！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "We are currently at G Stadium! Phew, the atmosphere here is on FIRE!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "這裡是G體育場！哇喔，觀眾席和賽場上都很火熱呢！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ขณะนี้เราอยู่ที่ G สเตเดี้ยม! ว๊าย บรรยากาศที่นี่ดูลุกเป็นไฟอย่างร้อนแรง!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Chúng tôi hiện đang ở Sân vận động G! Phù, bầu không khí ở đây đang cực CHÁY ạ!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "这里是G体育场！——哇哦，观众席和赛场上都热火朝天呢！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Wir sind derzeit im G-Stadion! Puh, die Stimmung hier ist kochend heiß!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Nous sommes actuellement au Stade G ! Et il y a une AMBIANCE DE FEU !"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "CHARADE_ACT4_STAGE1_START@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 5400402
L32_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "UNIT_SERIOUS"
L32_1.m_Face = L33_1
L33_1 = "MITCH_NPC_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "R"
L33_1 = "아휴, 덥다~ 이런 열기 속에선 밋치도 가드가 살짝 느슨해져 버릴지도~?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "もう、暑い～こんな熱気の中では、ミッチーもちょっとガードが緩くなっちゃうかも～？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "It's so hot in here... Maybe even Mitchie might loosen up a little in this heat, fu fuu!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "好熱喔～在這種火熱的氣氛裡，說不定米琪的防禦也會鬆懈一點點喔～？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ที่นี่ช่างร้อนจริงๆ... บางทีมิทชี่ก็อาจจะต้องไปหาวิธีคลายความร้อนนี้บ้าง ฟู ฟู!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Thật là nóng quá đi... Có lẽ ngay cả Mitchie cũng phải thả lỏng một chút trong cái nóng này, fu fuu!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "好热啊~在这种火热的氛围里，说不定米琪的防御也会松懈一点点哦~？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Es ist so heiß hier drin ... Vielleicht dürften diese Temperaturen sogar mir ein wenig die Gedanken vernebeln! Hehe!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Il fait tellement chaud ici... Peut-être que votre Mitchie pourrait se détendre un peu dans cette chaleur..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "CHARADE_ACT4_STAGE1_START@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 5400402
L33_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_LAUGH"
L34_1 = "MITCH_NPC_NULL_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "L_F_R"
L33_1.m_Pos = L34_1
L34_1 = "하지─만☆ 경기에 나올 선수들은 방심해선 안 되겠지?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "でーも☆ 試合に出る選手たちは、気を抜いちゃダメだよね？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "But! ☆ That will be a big no-no for the players attending tonight, eh?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "但—是☆參加比賽的選手們可不能掉以輕心喔？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "แต่! ☆ นั่นจะเป็นครั้งสำคัญที่พลาดไม่ได้สำหรับผู้เล่นที่เข้าร่วมคืนนี้ ว่ามั้ย?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Nhưng! ☆ Với những người chơi tham dự tối nay thì không thể nào thả lòng được phải không nào?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "但——是——呢☆参加比赛的选手们可不能掉以轻心呀？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Aber! ☆ Die Teilnehmer des heutigen Spiels dürfen sich nicht ablenken lassen, alles klar?!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Mais☆... Les joueurs de ce soir ne seraient peut-être pas d'accord !"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "CHARADE_ACT4_STAGE1_START@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 5400402
L34_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "MITCH_NPC_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "L"
L35_1 = "조심 또 조심! 여기서 무릎 까졌다고 울다간 평생 넷튜브 박제형이니까!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "用心、用心！　ここで膝を擦りむいたからって泣いたら、一生ネットチューブに晒されるよ！"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Caution is key, fellas! You'll become a meme if you bawl your eyes out here!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "小心駛得萬年船！如果因為在這裡跌倒就哭哭，那影片可是會在網路上永遠流傳的喔！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ต้องหากุญแจสำคัญให้เจอ ! พวกคุณจะกลายเป็นคนไร้ค่าถ้าคุณละสายตาจากที่นี่!"
L34_1.m_Talk_THA = L35_1
L35_1 = "Thận trọng là chìa khóa! Nếu không cẩn thận mà trợn mắt thì bạn sẽ là meme nổi nhất đấy nhé!"
L34_1.m_Talk_VTN = L35_1
L35_1 = "小心再小心！如果在这里因为摔破了膝盖就哭鼻子，可是会一辈子都被挂在NetTube上公开展览哦！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Seid stets auf der Hut! Wenn ihr hier ein paar Tränen vergießt, nur weil ihr euch am Knie verletzt habt, werdet ihr für den Rest eures Lebens zu einem Meme auf NetTube!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "La prudence est de mise ! Vous pourriez devenir un véritable meme si vous vous mettez à chouiner !"
L34_1.m_Talk_FRA = L35_1
