L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "UNIT_SERIOUS"
L37_1.m_Face = L38_1
L37_1.m_CharStrID = "STAFF_CANARY_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "스타디움 경기장 구조는 다들 숙지했지?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "スタジアム競技場の構造、みんな熟知してるよね？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Is everyone familiar with the stadium structure?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "體育場的賽場結構大家都熟悉了吧？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ทุกคนคุ้นเคยกับโครงสร้างสนามกีฬาหรือปล่าว?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Kết cấu của sân vận động mọi người đều quen thuộc hết rồi nhỉ?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "体育场的赛场结构大家都熟悉了吧？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Sind alle mit der Struktur des Stadions vertraut?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Est-ce que tout le monde est familier avec la structure du stade ?"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "CHARADE_ACT4_STAGE1_START@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 5400402
L38_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "STAFF_CANARY_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "각 건물들의 지하실을 통해 들어갈 수 있는 통로가 방어 측 거점으로 통해."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "各建物の地下室を通じて入れる通路が、防御側の拠点に繋がってる。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "There are passages that can be entered through the basement of each building, which leads to the defense base."
L38_1.m_Talk_ENG = L39_1
L39_1 = "各個建築的地下室都有通向防守方據點的通道。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "มีทางเดินที่สามารถเข้าไปได้ทางชั้นใต้ดินของแต่ละอาคาร ซึ่งจะนำไปสู่ฐานป้องกันของพวกมัน"
L38_1.m_Talk_THA = L39_1
L39_1 = "Có thể thông qua tầng hầm của các tòa nhà để tới căn cứ phòng thủ của đối phương."
L38_1.m_Talk_VTN = L39_1
L39_1 = "各个建筑的地下室都有通向守方的据点的通道。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Es gibt Durchgänge, die durch den Keller jedes Gebäudes betreten werden können und zur Verteidigungsbasis führen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Il existe des accès conduisant à la base de défense qui permettent d'entrer dans chaque bâtiment depuis le sous-sol."
L38_1.m_Talk_FRA = L39_1
