L42_1 = "CHARADE_ACT4_STAGE1_START@91#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 5400402
L41_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "STAFF_CANARY_NULL_NULL"
L42_1 = "1차 저지는 건물들을 활용해서, 보급한 뒤의 2차 저지는 지하에서 이루어지는 흐름이야."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "1次阻止は建物を活用して、補給してからの2次阻止は地下で行われる流れだよ。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "The first blockade will be held using the buildings, and the second one will be held underground, after each team's supplies are replenished."
L41_1.m_Talk_ENG = L42_1
L42_1 = "這就表示著第一次攔截會發生在建築周邊，第二次則會在雙方都得到重新補給後的地下。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "การปิดล้อมครั้งแรกจะจัดขึ้นโดยใช้สิ่งก่อสร้าง และครั้งที่สองจะถูกจัดไว้ที่ใต้ดิน หลังจากเติมเสบียงของแต่ละทีมแล้ว"
L41_1.m_Talk_THA = L42_1
L42_1 = "Cuộc phong tỏa đầu tiên sẽ được tổ chức bằng cách lợi dụng các tòa nhà và cuộc phong tỏa thứ hai sẽ ở dưới lòng đất, sau khi mỗi đội đã bổ sung vật tư."
L41_1.m_Talk_VTN = L42_1
L42_1 = "这就意味着第一次拦截会发生在建筑外围，第二次则会在双方都得到重新补给后的地下。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Die erste Blockade wird in den Gebäuden abgehalten und die zweite unter der Erde, nachdem die Vorräte jedes Teams wieder aufgefüllt sind."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Le premier blocus sera mis en place en utilisant les bâtiments, et le second aura lieu en sous-sol, après que les provisions de chaque équipe auront été réapprovisionnées."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "CHARADE_ACT4_STAGE1_START@92#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 92
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 5400402
L42_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "UNIT_DESPAIR"
L42_1.m_Face = L43_1
L42_1.m_CharStrID = "STAFF_CANARY_NULL_NULL"
L43_1 = "단, 이번 경기는 중간에 조명이 꺼지면서 5분간 암전으로 전환될 거야."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ただし、今度の試合は途中で照明が消えて、5分間暗転になる。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Keep in mind that there will be a five-minute lights-out event during the match!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "但是，這場比賽中途會關掉照明設備，轉換成5分鐘的夜戰模式。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "อย่าลืมว่าจะมีกิจกรรมแสงสีไฟเป็นเวลา 5 นาทีในระหว่างการแข่งขัน!"
L42_1.m_Talk_THA = L43_1
L43_1 = "Hãy nhớ rằng sẽ có một sự kiện tắt đèn kéo dài năm phút trong trận đấu!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "但是，这场比赛中途会关掉照明灯，转入5分钟的夜战模式。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Denkt daran, dass es während des Spiels einen fünfminütigen Licht-Aus-Trick geben wird!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Gardez à l'esprit qu'il y aura une extinction des lumières de 5 minutes pendant le match."
L42_1.m_Talk_FRA = L43_1
