L46_1 = "CHARADE_ACT4_STAGE1_START@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 5400402
L45_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "STAFF_CANARY_NULL_NULL"
L45_1.m_Pos = "C"
L46_1 = "주 조명은 여기, 방어 거점 바로 뒤에 있어."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "主照明はここ、防御拠点のすぐ後ろにある。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "The main lighting is here, right behind the defense base."
L45_1.m_Talk_ENG = L46_1
L46_1 = "主要照明在這裡，就在防守據點後面。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "แสงหลักอยู่ที่นี่ ด้านหลังฐานป้องกัน"
L45_1.m_Talk_THA = L46_1
L46_1 = "Ánh sáng chính, ở ngay phía sau căn cứ phòng thủ."
L45_1.m_Talk_VTN = L46_1
L46_1 = "主照明在这里，就在防御据点后面。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Die Hauptbeleuchtung ist hier, direkt hinter der Verteidigungsbasis."
L45_1.m_Talk_DEU = L46_1
L46_1 = "L'éclairage principal est là, juste derrière la base de défense."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "CHARADE_ACT4_STAGE1_START@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 5400402
L46_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "STAFF_CANARY_NULL_NULL"
L46_1.m_Pos = "C"
L47_1 = "암전 기믹이 끝난 직후가 반격 타이밍이야. 우리에게 허락된 유일한 이점이지."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "暗転ギミックが終わった直後が反撃するタイミングだよ。私たちに許された唯一の利点ね。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Our chance for attacking back will be right after the lights-out gimmick. It's the only advantage we have."
L46_1.m_Talk_ENG = L47_1
L47_1 = "夜戰機關結束後就是反擊的時機，這也是我們唯一的優勢。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "โอกาสในการโจมตีกลับของเราจะเกิดขึ้นหลังจากปิดไฟ มันเป็นข้อได้เปรียบเดียวที่เรามีตอนนี้"
L46_1.m_Talk_THA = L47_1
L47_1 = "Cơ hội phản công của chúng ta sẽ đến ngay sau trò tắt đèn. Đó là ưu thế duy nhất của chúng ta."
L46_1.m_Talk_VTN = L47_1
L47_1 = "夜战机关结束后就是反击的时机，这也是我们唯一的优势。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Unsere Chance zum Gegenangriff besteht direkt nach dem Licht-Aus-Trick. Das ist der einzige Vorteil, den wir haben."
L46_1.m_Talk_DEU = L47_1
L47_1 = "On aura une chance de contre-attaque lors du retour de la lumière. C'est le seul avantage qu'on a."
L46_1.m_Talk_FRA = L47_1
