L50_1 = "CHARADE_ACT4_STAGE1_START@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 5400402
L49_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "UNIT_HATE"
L49_1.m_Face = L50_1
L49_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L49_1.m_Pos = "R"
L50_1 = "처형식이 잘 보이라고 저기 세워 둔 게 아니라?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "処刑がよく見えるように、あっちに立たせておいたんじゃないのか？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Don't you think that light is more of a spotlight for our execution?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "確定那個設備不是給我們公開處刑的聚光燈嗎？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "เธอไม่คิดว่าแสงนั้นจะเป็นจุดสนใจทำให้ฆ่าซีวิตของเรามากกว่าหรอ?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Không phải ánh sáng đó là để chiếu trọn buổi hành quyết chúng ta sao?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "就我觉得那个设备像是给我们进行公开处刑的聚光灯吗？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Glaubst du nicht, dass dort das Licht angebracht wurde, damit man die Hinrichtungszeremonie besser sehen kann?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Ces lumières, c'est plutôt pour qu'on voit mieux le moment où on se fait dézinguer."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "CHARADE_ACT4_STAGE1_START@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 5400402
L50_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L50_1.m_Pos = "R"
L51_1 = "준비했던 전술은 죄다 무용지물이지, 상대가 어디서 구르다 왔는지도 모르지."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "用意してた戦術は全部無駄になったし、相手はどんなやつらなのかさっぱりだし。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Everything we prepared is useless, and we don't even know who our opponents are."
L50_1.m_Talk_ENG = L51_1
L51_1 = "先前準備的戰術完全派不上用場，對手也不知道是從哪冒出來的。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ทุกสิ่งที่เราเตรียมมานั้นไม่มีประโยชน์ แล้วเราก็ไม่รู้ด้วยซ้ำว่าใครคือคู่ต่อสู้ของเรา"
L50_1.m_Talk_THA = L51_1
L51_1 = "Mọi thứ chúng tôi đã chuẩn bị đều vô dụng, chúng tôi còn chẳng biết đối thủ của mình là ai nữa."
L50_1.m_Talk_VTN = L51_1
L51_1 = "准备的战术没用了，对手也不知道是从哪里冒出来的。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Alle von uns vorbereiteten Taktiken sind nutzlos und wir wissen nicht einmal, wer unsere Gegner sind."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Tout ce qu'on a préparé est inutile. Et on ne sait même pas qui sont nos adversaires."
L50_1.m_Talk_FRA = L51_1
