L2_1 = "잠옷 바람으로 현장에 던져 놔도 이것보단 낫겠다."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "パジャマ姿で現場にぶち込まれても、これよりはマシだろ。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I'd rather fight in my pajamas."
L1_1.m_Talk_ENG = L2_1
L2_1 = "我看我乾脆直接穿著睡衣上場。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ฉันอยากจะต่อสู้ในชุดนอนสบายๆของฉัน"
L1_1.m_Talk_THA = L2_1
L2_1 = "Tôi thà mặc pajama chiến đấu còn hơn."
L1_1.m_Talk_VTN = L2_1
L2_1 = "不如让我穿着睡衣上场好了。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Ich könnte auch gleich in meinem Schlafanzug antreten."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Autant se battre en pyjama."
L1_1.m_Talk_FRA = L2_1
