L6_1 = "CHARADE_ACT4_STAGE1_START@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 5400402
L5_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "UNIT_DESPAIR"
L5_1.m_Face = L6_1
L5_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L5_1.m_Pos = "R"
L6_1 = "아쉬워요. 제가 아니라 미나 선배였으면 상대가 누구든 전부 한 방 감일 텐데."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "残念ですね。私じゃなくてミナ先輩だったら、相手が誰でもみんな一発でやっつけられるはずなのに。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "What a shame. If it was Mina instead of me, they would all be taken down with one blow."
L5_1.m_Talk_ENG = L6_1
L6_1 = "真可惜，如果是米娜前輩的話，不管對手是誰都能一下子打趴吧。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ช่างน่าเสียดาย น่าจะเป็นมีนาแทนฉัน พวกเขาทั้งหมดจะได้ถูกสังหารในครั้งเดียวเลย"
L5_1.m_Talk_THA = L6_1
L6_1 = "Xấu hổ làm sao. Nếu đó là Mina chứ không phải tôi thì tất cả bọn họ sẽ bị hạ gục chỉ sau một đòn."
L5_1.m_Talk_VTN = L6_1
L6_1 = "真可惜，如果是米娜前辈的话，不管对手是谁都能一下子打趴下吧。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Wie schade. Wenn es Mina wäre und nicht ich, würden alle Gegner mit einem Schlag erledigt sein."
L5_1.m_Talk_DEU = L6_1
L6_1 = "C'est vraiment dommage. Si Mina pouvait me remplacer, elle n'en ferait qu'une bouchée."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
