L8_1 = "CHARADE_ACT4_STAGE1_START@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 5400402
L7_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "m_Action"
L9_1 = "SELECT"
L7_1[L8_1] = L9_1
L8_1 = "m_ActionStrKey"
L9_1 = "MARK4"
L7_1[L8_1] = L9_1
L8_1 = "노엘 양. 소대장 대행은 부상자라네."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "ノエル君。小隊長代行は怪我人だ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Noelle. Please remember that your temporary commander is injured."
L7_1.m_Talk_ENG = L8_1
L8_1 = "洛艾兒，代理小隊長現在是病人喔。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "โนเอล จำไว้ว่าผู้บัญชาการชั่วคราวของคุณได้รับบาดเจ็บ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Noel. Hãy nhớ rằng chỉ huy tạm thời của cô đang bị thương."
L7_1.m_Talk_VTN = L8_1
L8_1 = "诺艾尔，代理小队长现在是伤员。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Noelle. Bitte denk daran, dass die amtierende Kommandantin verletzt ist."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Noelle. N'oublie pas que ta commandante temporaire est blessée."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "CHARADE_ACT4_STAGE1_START@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 5400402
L8_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_SURPRISE"
L9_1 = "m_Action"
L10_1 = "MARK"
L8_1[L9_1] = L10_1
L9_1 = "m_ActionStrKey"
L10_1 = "MARK4"
L8_1[L9_1] = L10_1
L8_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L8_1.m_Pos = "R"
L8_1.m_Crash = 20
L9_1 = "앗, 맞다! 그랬죠! 죄송해요! 선배!"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "あっ、そうだ！　そうでしたね！　ごめんなさい！　先輩！"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Oh, right! Sorry, Mina!"
L8_1.m_Talk_ENG = L9_1
L9_1 = "哎呀，對欸！對不起！前輩！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "โอ้วใช่! ขอโทษนะมีนา!"
L8_1.m_Talk_THA = L9_1
L9_1 = "Ô đúng rồi! Em xin lỗi Mina!"
L8_1.m_Talk_VTN = L9_1
L9_1 = "啊，没错！对不起！前辈！"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ach ja, stimmt! Entschuldigung, Mina!"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Oh, c'est vrai. Désolée, Mina !"
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "CHARADE_ACT4_STAGE1_START@109#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 5400402
L9_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "MINA_FENRIR_CHIEF_NULL"
L9_1.m_Pos = "L"
L10_1 = "아냐. 나도 상대가 하는 짓이 마음에 드는 건 아니니까."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "いや。私も相手のやってることが気に入ってるわけじゃないから。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Don't mention it. I don't like what they're doing either."
L9_1.m_Talk_ENG = L10_1
L10_1 = "沒事，我也不喜歡對方的做法。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "อย่าพูดถึงมัน ฉันเองก็ไม่ชอบสิ่งที่พวกเขากำลังทำเหมือนกัน"
L9_1.m_Talk_THA = L10_1
L10_1 = "Không sao. Tôi cũng không thích việc họ đang làm."
L9_1.m_Talk_VTN = L10_1
L10_1 = "没事，我也不喜欢对方的做法。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Schon gut. Mir gefällt es auch ganz und gar nicht, was unsere Gegner hier abziehen."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Oh, t'en fais pas. Moi non plus j'aime pas trop leurs manières."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
