L13_1 = "CHARADE_ACT4_STAGE1_START@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 5400402
L12_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_PRIDE"
L12_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L12_1.m_Pos = "L"
L13_1 = "괜찮아요. 지금까지 계속 로비도 없이 싸웠으니까요. 조금 더 불리해졌을 뿐이에요."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "大丈夫です。これまでずっとロビー活動なしで戦ってきたんですから。さらにちょっとだけ不利になっただけです。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "It's okay. We've been fighting all this time without even lobbying. It's just a little harder this time."
L12_1.m_Talk_ENG = L13_1
L13_1 = "沒關係，之前我們也是在沒行賄的狀態下進行比賽的，現在情勢只有比之前更不利一點而已。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ไม่เป็นไร ถึงเราเคยต่อสู้มาตลอดโดยไม่ได้วิ่งเต้นเยอะอะไร แต่ว่าคราวนี้อาจจะยากหน่อยสำหรับพวกเรา"
L12_1.m_Talk_THA = L13_1
L13_1 = "Không sao đâu. Chúng tôi đã chiến đấu suốt thời gian qua mà không hối lộ. Lần này chỉ bất lợi hơn một chút thôi."
L12_1.m_Talk_VTN = L13_1
L13_1 = "没关系，之前我们也是在没行贿的状态下进行的比赛。现在只是更不利了一点而已。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Es ist okay. Wir haben die ganze Zeit gekämpft, ohne überhaupt Lobbyismus zu betreiben. Diesmal ist es halt etwas schwieriger."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Ça va aller. On s'est battu sans aide extérieure jusqu'ici. Ça va juste être un peu plus dur cette fois-ci."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "CHARADE_ACT4_STAGE1_START@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 5400402
L13_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L13_1.m_Pos = "L"
L14_1 = "이렇게까지 했는데 저희가 이기면 그릴 파티는 폐업 확정이죠. 꼴 좋다."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ここまでやっても私たちが勝つなら、グリルパーティーは廃業確定です。ざまあみろ。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "If we win this match, then Grill Party is doomed for sure. Suckers!"
L13_1.m_Talk_ENG = L14_1
L14_1 = "反倒是他們搞這麼多小動作，如果還輸給我們的話，那格里爾派提真的就準備關門大吉吧。想到就開心。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "หากเราชนะแมตช์นี้ กริลล์ปาร์ตี้ก็ต้องถึงวาระสุดท้ายแน่นอน !"
L13_1.m_Talk_THA = L14_1
L14_1 = "Nếu chúng ta thắng trận này, thì Grill Party chắc chắn sẽ bị tiêu diệt. Bọn khốn!"
L13_1.m_Talk_VTN = L14_1
L14_1 = "反过来想，搞了这么多事，如果还让我们赢了，格利尔肯定永远完蛋了。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Wenn wir dieses Spiel gewinnen, ist Grill Party mit Sicherheit zum Scheitern verurteilt."
L13_1.m_Talk_DEU = L14_1
L14_1 = "L'équipe Barbecue est condamnée si elle perd ce match. Bande de ratés."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "CHARADE_ACT4_STAGE1_START@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 5400402
L14_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_IDLE"
L14_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L14_1.m_Pos = "R"
L15_1 = "뭐, 일단 아까 대기실을 염탐하면서 선수 명단을 슬쩍 확인해 봤는데…."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "ま、とりあえずさっき控え室を探ってて、選手のリストをちらっと確認したんだけど……"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Well. I did take a peek at their entry list in the waiting room..."
L14_1.m_Talk_ENG = L15_1
L15_1 = "嗯，剛才在休息室裡，我有偷看一下選手名單……"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ดี ฉันจะแอบดูรายการของพวกเขาในห้องรอ..."
L14_1.m_Talk_THA = L15_1
L15_1 = "Chà. Tôi đã xem qua danh sách đăng ký của họ lúc chờ..."
L14_1.m_Talk_VTN = L15_1
L15_1 = "嗯，刚才在休息室里我偷偷地看了一下选手名单……"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ich habe einen Blick auf ihre Teilnehmerliste im Wartezimmer erhaschen können, aber ..."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Bon. J'ai pu jeter un coup d'œil à leur liste des participants dans la salle d'attente..."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "CHARADE_ACT4_STAGE1_START@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 5400402
L15_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L15_1.m_Pos = "R"
L16_1 = "그릴 파티에서 못 본 얼굴들이 잔뜩 있더라. 아마 신형 장비를 입고 온 녀석들이겠지."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "グリルパーティーでは見なかった顔だらけだったよ。たぶん、新型の装備をつけてきたやつらだろ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Most of them were not from Grill Party. They're probably all suited up with state-of-the-art equipment."
L15_1.m_Talk_ENG = L16_1
L16_1 = "格里爾派提的小隊中有很多沒見過的生面孔。他們應該是穿著新型裝備來的。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "พวกเขาส่วนใหญ่ไม่ได้มาจาก กริลล์ปาร์ตี้ พวกนั้นน่าจะเหมาะกับอุปกรณ์ล้ำสมัย"
L15_1.m_Talk_THA = L16_1
L16_1 = "Hầu hết chúng không đến từ Grill Party. Có lẽ tất cả chúng đều mang trang bị tối tân."
L15_1.m_Talk_VTN = L16_1
L16_1 = "格利尔的小队中有很多没见过的生面孔。他们应该是穿着新型装备来的。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Die meisten von ihnen gehören nicht zu Grill Party. Sie sind wahrscheinlich alle mit modernster Ausrüstung ausgestattet."
L15_1.m_Talk_DEU = L16_1
L16_1 = "La plupart de leurs participants ne font pas partie de l'équipe Barbecue. Ils sont probablement tous équipés avec du matériel de pointe."
L15_1.m_Talk_FRA = L16_1
