L20_1 = "好像和鋼鐵之軀的標準強化服不一樣。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "พวกเขาดูแตกต่างจากพาวเวอร์สูทมาตรฐานจากสตีลเลน"
