L21_1 = "CHARADE_ACT4_STAGE1_START@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 5400402
L20_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "STAFF_CANARY_NULL_NULL"
L20_1.m_Pos = "C"
L21_1 = "네. 민간에 판매하기 전에 테스트용으로 공급한 모델 같아요."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "はい。民間に販売する前に、テスト用として供給したモデルみたいです。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Yes. They looked like prototypes that were provided for testing before sales."
L20_1.m_Talk_ENG = L21_1
L21_1 = "沒錯，這應該是賣到民營市場前的測試型號。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ใช่ พวกเขาดูเหมือนโมเดลที่มีไว้สำหรับการทดสอบก่อนการจำหน่าย"
L20_1.m_Talk_THA = L21_1
L21_1 = "Đúng. Chúng trông giống như nguyên mẫu được cung cấp để thử nghiệm trước khi bán."
L20_1.m_Talk_VTN = L21_1
L21_1 = "没错，这应该是转为民用出售前的测试用型号。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ja. Sie sahen aus wie Prototypen, die vor dem Verkauf zum Testen bereitgestellt wurden."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Oui. Ce sont sûrement des prototypes. Le genre d'équipements qui sont testés avant leur mise en vente."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "CHARADE_ACT4_STAGE1_START@121#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 5400402
L21_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "STAFF_CANARY_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "최신 트렌드에 맞췄으면 신체 능력 증강 기능이 메인이겠죠."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "最新のトレンドに合わせてるなら、身体能力を増強する機能がメインでしょう。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "If it's brand new, they would've probably focused on enhancing the physical abilities."
L21_1.m_Talk_ENG = L22_1
L22_1 = "如果是最新的那幾款，主要功能應該是增強體能。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "หากเป็นแบรนด์ใหม่ พวกเขาคงจะมุ่งเน้นไปที่การเพิ่มความสามารถทางกายภาพมากกว่า"
L21_1.m_Talk_THA = L22_1
L22_1 = "Nếu nó là thương hiệu mới, có lẽ chúng sẽ tập trung tăng cường khả năng thể chất."
L21_1.m_Talk_VTN = L22_1
L22_1 = "如果是最新的那几款，主要功能应该是增强身体能力。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Wenn sie brandneu wären, hätten sie sich wahrscheinlich auf die Verbesserung der körperlichen Fähigkeiten konzentriert."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Si c'est vraiment des modèles dernier cri, ils auront mis l'accent sur l'amélioration des capacités physiques."
L21_1.m_Talk_FRA = L22_1
