L33_1 = "UNIT_SERIOUS"
L32_1.m_Face = L33_1
L32_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "경기 중에 실시간으로 지시를 내려 주세요. 전황은 스키너가 가르쳐 줄 거예요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "試合中にリアルタイムで指示してください。戦況はスキナーが教えてくれます。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Give us instructions in real-time throughout the match. Skinner will inform you of the situation."
L32_1.m_Talk_ENG = L33_1
L33_1 = "比賽期間請隨時下達指示。史金納會告訴你戰況。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ให้คำแนะนำแบบเรียลไทม์ตลอดการแข่งขัน สกินเนอร์จะแจ้งให้คุณทราบถึงสถานการณ์"
L32_1.m_Talk_THA = L33_1
L33_1 = "Hãy ra chỉ dẫn cho bọn tôi trong thời gian thực trong suốt trận đấu. Skinner sẽ thông báo cho ngài tình hình."
L32_1.m_Talk_VTN = L33_1
L33_1 = "比赛期间请实时下达指示。斯金纳会告诉你战况。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Geben Sie uns während des Spiels in Echtzeit Anweisungen. Skinner wird Sie über die Situation auf dem Laufenden halten."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Donnez-nous des instructions en temps réel pendant le match. Skinner vous tiendra informé de la situation."
L32_1.m_Talk_FRA = L33_1
