L33_1.m_Pos = "C"
L34_1 = "지휘권을 포기하겠다는 거야, 너?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "あんた、指揮権をあきらめるってことか？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Are you giving up your commanding authority?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "你這是要放棄指揮權的意思？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เธอกำลังละทิ้งอำนาจการบังคับบัญชาของเธอหรือป่าว?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Nhóc từ bỏ quyền chỉ huy á?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "你这是要放弃指挥权吗？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Gibst du deine Befehlsgewalt auf?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Tu abandonnes ton commandement ?"
