L36_1.m_Bounce = L37_1
L37_1 = "직무유기다!! 저 충격 받았어요!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "職務怠慢！！　ショックです！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "This is a dereliction of duty! I'm shocked!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "震驚！你這是怠忽職守欸！！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "นี่คือการละทิ้งหน้าที่! นี่เธอทำฉันซ๊อกไปเลย!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Thật là vô trách nhiệm! Tôi bị sốc!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "哇呜！你那是玩忽职守！！菲利塞特！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Das ist eine Pflichtverletzung! Ich bin geschockt!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "C'est un manquement à ton devoir ! Je suis choquée !"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "CHARADE_ACT4_STAGE1_START@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 5400402
L37_1.m_CutScenStrID = "CHARADE_ACT4_STAGE1_START"
