L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "MINA_FENRIR_CHIEF_NULL"
L37_1.m_Pos = "R"
L38_1 = "……진정해. 그런 게 아니야, 노엘."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "……落ち着いて。それは違うよ、ノエル。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "...Relax. It's different, Noelle."
L37_1.m_Talk_ENG = L38_1
L38_1 = "……你冷靜點，不是那樣的，洛艾兒。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "...ใจเย็น มันต่างกัน โนเอล"
L37_1.m_Talk_THA = L38_1
L38_1 = "…Bình tĩnh nào. Cái này khác, Noelle."
L37_1.m_Talk_VTN = L38_1
L38_1 = "……你冷静点，不是那样的，诺艾尔。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "... Entspann dich mal. Darum geht es gar nicht, Noelle."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Du calme, Noelle... C'est différent cette fois."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
