L39_1.m_Pos = "R"
L40_1 = "기억 안 나? 시뮬레이터를 사용할 때 네가 말했잖아."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "覚えてないの？　シミュレーターを使ったときに、あなたが言ったこと。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Don't you remember? You said it yourself when using the simulator."
L39_1.m_Talk_ENG = L40_1
L40_1 = "你不記得了嗎？你自己在使用模擬器時說過的話？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เธอจำไม่ได้เหรอ? เธอพูดเองตอนที่ใช้โปรแกรมจำลอง"
L39_1.m_Talk_THA = L40_1
L40_1 = "Không nhớ sao? Cô đã tự nói khi tập với trình giả lập mà."
L39_1.m_Talk_VTN = L40_1
L40_1 = "你不记得了吗？你自己不也说过吗。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Erinnerst du dich nicht? Du hast es doch selbst gesagt, als du den Simulator benutzt hast."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Tu ne te souviens pas ? C'est pourtant toi qui l'a dit au simulateur."
L39_1.m_Talk_FRA = L40_1
