L42_1[L43_1] = L44_1
L43_1 = "노엘은 싸울 줄 몰라요. 일반인인 저보다 체력도 약하구요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ノエルさんは戦い方をわかっていません。一般人である私より体力も足りないですし。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Noelle doesn't know how to fight. She's weaker than me, a non-Counter."
L42_1.m_Talk_ENG = L43_1
L43_1 = "洛艾兒不會戰鬥，體力比我這個一般人還差。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "โนเอลไม่รู้ว่าจะต่อสู้ยังไง เธออ่อนแอกว่าฉัน เธอไม่ใช่เคาน์เตอร์"
L42_1.m_Talk_THA = L43_1
L43_1 = "Noelle không biết đánh nhau. Cô ấy còn yếu hơn tôi, một người còn không phải Counter."
L42_1.m_Talk_VTN = L43_1
L43_1 = "诺艾尔不会战斗，体力也比普通人的我还差。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Noelle weiß nicht, wie man kämpft. Sie ist schwächer als ich, obwohl sie ein Counter ist."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Noelle ne sait pas se battre. Elle est plus faible que moi, alors que je ne suis même pas un Counter."
L42_1.m_Talk_FRA = L43_1
