L45_1 = 0.3
L43_1[L44_1] = L45_1
L44_1 = "나름대로 재능은 있는 편이야. 3종 침식체에게 기습당한 용병들을 혼자 구출해냈으니까."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "それなりに才能はある方だよ。第3種侵食体に奇襲された傭兵たちを一人で助けたんだから。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "She's kind of talented, in fact. Noelle rescued a bunch of mercenaries who were attacked by a Category 3 C.O. on her own."
L43_1.m_Talk_ENG = L44_1
L44_1 = "她其實蠻有天分的，以前還曾經獨自救出被3類侵蝕體攻擊的傭兵。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "อันที่จริงเธอค่อนข้างมีความสามารถ โนเอลช่วยชีวิตทหารรับจ้างกลุ่มหนึ่งที่ถูกโจมตีจากวัตถุคอร์รัปต์คลาส 3 ด้วยตัวเธอเอง"
L43_1.m_Talk_THA = L44_1
L44_1 = "Trên thực tế, cô ấy khá tài năng. Noelle đã tự mình giải cứu một nhóm lính đánh thuê khi bị V.T.A.M. loại 3 tấn công."
L43_1.m_Talk_VTN = L44_1
L44_1 = "她其实挺有天赋的。以前还独自救出了被3级侵蚀体攻击的佣兵。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Sie ist eigentlich ziemlich talentiert. Noelle hat im Alleingang eine Gruppe Söldner, die von einem C.°O. der Kategorie 3 angegriffen wurden, gerettet."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Elle est plutôt talentueuse, en fait. Elle a déjà sauvé des mercenaires qui étaient attaqués par un O.C. de catégorie 3."
L43_1.m_Talk_FRA = L44_1
