L48_1 = "에헤헤, 사장님의 지시 덕분이지만요."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "えへへ、社長が指示してくれたおかげですけどね。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Eh he he, it's all thanks to Boss's orders."
L47_1.m_Talk_ENG = L48_1
L48_1 = "嘿嘿嘿，都是老闆的指示下得好。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เฮ้ เฮ้ ทั้งหมดนี้ต้องขอบคุณคำสั่งของบอส"
L47_1.m_Talk_THA = L48_1
L48_1 = "Ơ he he, tất cả là nhờ Ông Chủ chỉ dẫn."
L47_1.m_Talk_VTN = L48_1
L48_1 = "哎嘿嘿，都是老板指示得好。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Hihihi, das ist alles nur den Anweisungen vom Boss zu verdanken."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Hé hé hé, je n'ai fait que suivre les ordres du boss."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "CHARADE_ACT4_STAGE1_START@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
