L48_1.m_Pos = "R"
L49_1 = "저 혼자선 허둥거리기만 하다 당했을 거예요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "私一人だったら、慌てるばかりでやられていたはずです。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "If I did it alone, I would've died hesitating."
L48_1.m_Talk_ENG = L49_1
L49_1 = "如果是我自己，可能只會手忙腳亂。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ถ้าฉันทำคนเดียว ฉันคงจะลังเลไม่กล้าตัดสินใจ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Nếu làm điều đó một mình, tôi sẽ chết ngay tức khắc."
L48_1.m_Talk_VTN = L49_1
L49_1 = "如果是我自己，可能只会手忙脚乱。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Wenn ich es alleine versucht hätte, hätte ich so lange gezögert, bis alle gestorben wären."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Seule, je serais probablement morte là-bas."
L48_1.m_Talk_FRA = L49_1
