L2_1 = "리더로서 전술을 결정할 수 있는 권리를 포기해서라도."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "リーダーとして戦術を決められる権利をあきらめてでも。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Even if it means giving up her commanding authority."
L1_1.m_Talk_ENG = L2_1
L2_1 = "即使要放棄身為隊長的決定權。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "แม้ว่านั่น หมายถึงการละทิ้งอำนาจการบังคับบัญชาของเธอ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Ngay cả khi nghĩa là từ bỏ quyền chỉ huy của mình."
L1_1.m_Talk_VTN = L2_1
L2_1 = "哪怕放弃作为队长决定战术的指挥权也在所不惜。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Auch wenn es bedeutet, dass sie als Anführerin das Recht aufgibt, über die Taktik zu entscheiden."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Elle même prête à transmettre son commandement pour ça."
L1_1.m_Talk_FRA = L2_1
