L3_1 = "절박할수록, 버리는 것도 쉬워지니까."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "差し迫るほど、簡単に捨てることもできるようになる。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "The more desperate you are, the easier it is to let things go."
L2_1.m_Talk_ENG = L3_1
L3_1 = "越是急迫的時候，放棄一些東西就越容易。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ยิ่งเธอหมดหวังมากเท่าไร ก็ยิ่งปล่อยวางได้ง่ายขึ้นเท่านั้น"
L2_1.m_Talk_THA = L3_1
L3_1 = "Càng tuyệt vọng, sẽ càng dễ buông bỏ mọi thứ."
L2_1.m_Talk_VTN = L3_1
L3_1 = "越是急迫的时候，放弃一些东西就越容易。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Je verzweifelter man ist, desto einfacher ist es, Dinge loszulassen."
L2_1.m_Talk_DEU = L3_1
L3_1 = "À situation désespérée, mesures desespérées."
L2_1.m_Talk_FRA = L3_1
