L6_1.m_Pos = "C"
L7_1 = "네. 저는 원래 어른들을 믿지 않아요."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "はい。私は元々大人たちを信じてません。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Yes. I never trust adults."
L6_1.m_Talk_ENG = L7_1
L7_1 = "……我本來是不相信大人的。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ใช่ ฉันไม่เคยไว้ใจผู้ใหญ่มาก่อน"
L6_1.m_Talk_THA = L7_1
L7_1 = "Vâng. Tôi không bao giờ tin người lớn."
L6_1.m_Talk_VTN = L7_1
L7_1 = "……我本来是不相信大人的。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ja. Ich vertraue eigentlich nie Erwachsenen."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Oui. Je ne fais jamais confiance aux adultes."
L6_1.m_Talk_FRA = L7_1
