L7_1.m_CharStrID = "FELICETTE_CANARY_NULL_NULL"
L7_1.m_Pos = "C"
L8_1 = "어른들은 전부 거짓말쟁이에, 잔인하니까요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "大人たちはみんな嘘つきで、残酷ですから。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "They are nothing but cruel liars."
L7_1.m_Talk_ENG = L8_1
L8_1 = "大人全都是不擇手段的騙子。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "พวกเขาไม่มีอะไรนอกจากคนโกหกที่โหดร้าย"
L7_1.m_Talk_THA = L8_1
L8_1 = "Họ chỉ toàn là kẻ dối trá độc ác."
L7_1.m_Talk_VTN = L8_1
L8_1 = "大人全都是残忍的骗子。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Alle Erwachsenen sind grausame Lügner."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Ce ne sont que des menteurs cruels."
L7_1.m_Talk_FRA = L8_1
