L10_1 = "コーチの能力は信じられると思います。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "I think I can count on your abilities."
L9_1.m_Talk_ENG = L10_1
L10_1 = "我覺得我可以相信教練的能力。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ฉันคิดว่าฉันไว้ใจในความสามารถของคุณ"
L9_1.m_Talk_THA = L10_1
L10_1 = "Tôi nghĩ rằng tôi có thể tin tưởng vào khả năng của ngài.."
L9_1.m_Talk_VTN = L10_1
