L10_1.m_Pos = "C"
L11_1 = "그러니까 지시를 내려 주세요. 결승까지 갈 수 있도록."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "だから、指示を出してください。決勝まで行けるように。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Please, give us orders. So that we can make it to the finals."
L10_1.m_Talk_ENG = L11_1
L11_1 = "所以請下達指示吧，讓我們打進決賽。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "โปรดสั่งเรา เพื่อให้เราผ่านเข้าสู่รอบชิงชนะเลิศ"
L10_1.m_Talk_THA = L11_1
L11_1 = "Hãy chỉ dẫn cho chúng tôi. Để chúng tôi có thể lọt vào trận chung kết."
L10_1.m_Talk_VTN = L11_1
L11_1 = "所以请下达指示吧，让我们打进淘汰赛。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Bitte geben Sie uns Anweisungen. Damit wir es ins Finale schaffen können."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Nous attendons vos ordres. Emmenez-nous en finale."
L10_1.m_Talk_FRA = L11_1
