L13_1.m_Crash = 20
L14_1 = "예선 최종 경기는 어느덧 여러분이 기대하던 4회차!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "予選の最終試合は、いよいよ皆さんが楽しみにしてた4回目！"
L13_1.m_Talk_JPN = L14_1
L14_1 = "It's the final match of the qualifiers! The fourth match you've all been waiting for!"
L13_1.m_Talk_ENG = L14_1
L14_1 = "這裡是預賽最後一輪比賽！也是大家期待已久的第四輪比賽啦！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "นี่ถึงนัดสุดท้ายของรอบคัดเลือกแล้ว! การแข่งขันนัดที่สี่ที่ทุกคนรอคอยมาแล้ว!"
L13_1.m_Talk_THA = L14_1
L14_1 = "Đây là trận đấu cuối cùng của vòng loại rồi! Cũng là trận thứ tư mà tất cả các bạn vẫn luôn chờ đợi!"
L13_1.m_Talk_VTN = L14_1
L14_1 = "这里是预选赛最后一轮比赛！也是大家期待已久的第四轮比赛啦！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Es ist das letzte Spiel der Qualifikationsrunde! Das vierte Spiel, auf das ihr alle schon sehnsüchtig gewartet habt!"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Voici le dernier match des qualifications ! Celui que vous attendiez tous !"
L13_1.m_Talk_FRA = L14_1
