L15_1 = "중계용 드론들은 세팅 완료! 이어지는 양 팀의 입장!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "中継用のドローンはセット完了！　続きまして、両チームの入場！"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Streaming drones all set! Ah, we see the players entering!"
L14_1.m_Talk_ENG = L15_1
L15_1 = "轉播用的無人機已經全部就定位！接下來是雙方隊伍進場！"
L14_1.m_Talk_TWN = L15_1
