L14_1.m_Talk_THA = L15_1
L15_1 = "Drone phát trực tuyến đã sẵn sàng! Ah, người chơi đang bước vào!"
L14_1.m_Talk_VTN = L15_1
L15_1 = "转播用的无人机已经全部就位了！接下来是双方队伍入场！"
L14_1.m_Talk_SCN = L15_1
