L16_1 = "L_F_C"
L15_1.m_Pos = L16_1
L16_1 = "공격 팀! 떠오르는 루키였지만 사채업자의 방망이질에 프라이드가 개박살났던 그 그릴 파티!"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "攻撃チーム！　新たなルーキーだったけど、貸金業者とひと悶着あってプライドが粉々になったあのグリルパーティー！"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Offensive team! The upcoming rookies that were battered down by a single iron pipe of a loan shark! Grill Party!"
L15_1.m_Talk_ENG = L16_1
L16_1 = "進攻方！雖然是最近崛起的新人，卻被高利貸業者的鐵管打碎所有驕傲的格里爾派提！"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ทีมรุก! มือใหม่ที่กำลังจะถูกทุบโดยท่อเหล็กเดียวของฉลามเงินกู้! กลิลล์ปาร์ตี้!"
L15_1.m_Talk_THA = L16_1
L16_1 = "Đội tấn công! Những tân binh đã bị hạ gục bởi một ống sắt duy nhất của một kẻ cho vay nặng lãi! Grill Party!"
L15_1.m_Talk_VTN = L16_1
L16_1 = "进攻方！虽然是最近崛起的新人，但却被高利贷者的棍棒打碎了所有骄傲的格利尔！"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Das offensive Team! Die aufstrebenden Neulinge, die von einem einzigen Eisenrohr eines Kredithais niedergeprügelt wurden! Grill Party!"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Pour l'équipe en attaque... Des petits nouveaux qui se sont fait malmener par une usurière et sa batte de fer ! L'équipe Barbecue !"
L15_1.m_Talk_FRA = L16_1
