L25_1[L26_1] = L27_1
L26_1 = "그래. 다들 우리가 자빠지는 꼴을 보고 싶어서 안달이 났어."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "そう。みんな私たちがやられる姿を見たくて仕方ないんだよ。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Yeah. They're all just waiting for us to make a fool of ourselves."
L25_1.m_Talk_ENG = L26_1
L26_1 = "就是說，大家都一副看衰我們的樣子。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ใช่ พวกเขาทั้งหมดกำลังรอดูพวกเราหลอกตัวเอง"
L25_1.m_Talk_THA = L26_1
L26_1 = "Yeah. Họ chỉ chờ ta thành kẻ ngốc thôi."
L25_1.m_Talk_VTN = L26_1
L26_1 = "是啊，大家都急着看我们摔倒的样子呢。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ja. Sie alle warten nur darauf, dass wir uns zum Narren machen."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Ouais. Il attendent juste qu'on se ridiculise."
L25_1.m_Talk_FRA = L26_1
