L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "だから、正気に戻るように後頭部を思いっきり殴ってやろうよ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "So let's give them a memorable performance."
L26_1.m_Talk_ENG = L27_1
L27_1 = "所以我們打起精神來，讓所有人大吃一驚！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ดังนั้น แสดงสิ่งที่น่าจดจำแก่พวกเขาไป"
L26_1.m_Talk_THA = L27_1
L27_1 = "Nên ta sẽ cho họ một màn trình diễn đáng nhớ."
L26_1.m_Talk_VTN = L27_1
L27_1 = "所以打起精神来吧，让他们都大吃一惊！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Also lasst uns einen so unvergesslichen Auftritt hinlegen, dass ihnen die Spucke wegbleibt."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Alors donnons-leur un spectacle mémorable."
