L30_1 = "<color=#ffd34c>물론이지. 좋은 활약 기대하겠네.</color>"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "<color=#ffd34c>もちろんだ。素敵な活躍、楽しみにしている。</color>"
L29_1.m_Talk_JPN = L30_1
L30_1 = "<color=#ffd34c>Yes. I wish you good luck.</color>"
L29_1.m_Talk_ENG = L30_1
L30_1 = "<color=#ffd34c>當然，我很期待你們的表現。</color>"
L29_1.m_Talk_TWN = L30_1
L30_1 = "<color=#ffd34c>ใช่ ผมขอให้พวกเธอโชคดี</color>"
L29_1.m_Talk_THA = L30_1
L30_1 = "<color=#ffd34c>Đương nhiên. Chúc cả team may mắn.</color>"
L29_1.m_Talk_VTN = L30_1
L30_1 = "<color=#ffd34c>当然，我期待你们的活跃表现。</color>"
L29_1.m_Talk_SCN = L30_1
