L33_1 = "하지만 놀랍게도 카나리아 스쿼드! 뭔가 단단히 각오한 표정!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "でも、驚くことにカナリア・スクワッド！　何か固く決意した顔！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Oh, what's this? Canary Squad looks extremely determined!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "哇喔！金絲雀小隊一副心意已決的樣子！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "โอ้ นี่คืออะไร? หน่วยแคนารีดูมุ่งมั่นสุดๆ!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Ồ, cái gì thế này? Tiểu đội Canary trông cực kỳ quyết tâm!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "哇哦！金丝雀小队一副做好了觉悟的表情！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Oh, der Canary Trupp sieht äußerst entschlossen aus!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Oh oh ! L'escouade Canari a l'air déterminée !"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
