L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "설마 진심으로 본선까지 올라갈 작정일까?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "まさか、本気で本戦まで行くつもりなのかな？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Are they really planning on making it to the elimination round?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "難道她們真的打算打入決賽？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "พวกเขาวางแผนที่จะออกจากรอบคัดเลือกกันหรือปล่าว?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Họ thực sự định lọt vào vòng chung kết sao?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "难道她们真的打算打入淘汰赛？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Haben sie wirklich vor, es bis ins Finale schaffen?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Ils veulent vraiment passer les qualifications on dirait !"
