L34_1.m_Pos = L35_1
L35_1 = "궁금하다면 전원, 채널 고정!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "皆さん、気になっているならチャンネルはそのままで！"
L34_1.m_Talk_JPN = L35_1
L35_1 = "If you're eager to find out, stay tuned!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "想知道的話，那就鎖定頻道別走開！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "หากพวกคุณอยากรู้ โปรดคอยติดตามต่อไป!"
L34_1.m_Talk_THA = L35_1
L35_1 = "Nếu háo hức muốn biết thì đừng có đi đâu đấy!"
L34_1.m_Talk_VTN = L35_1
L35_1 = "想知道的话，那就锁定频道别走开！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Wenn ihr es unbedingt herausfinden möchtet, bleibt auf jeden Fall dran!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Restez sur ma chaîne si vous voulez connaître l'issue du combat !"
L34_1.m_Talk_FRA = L35_1
