L35_1.m_CharStrID = L36_1
L36_1 = "R_F_L"
L35_1.m_Pos = L36_1
L36_1 = "화장실 다녀오려면 지금이 기회야! 경기는 광고 후에 바로 시작된다구~?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "トイレに行きたかったら今がチャンス！　試合は、CMの後にすぐ始まっちゃうよ～？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "This is your last chance to go to the bathroom! The match starts right after the ad!"
L35_1.m_Talk_ENG = L36_1
L36_1 = "現在就是去洗手間的最好的時機！廣告之後比賽馬上開始～？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "นี่เป็นโอกาสสุดท้ายที่คุณจะได้ลุกเข้าห้องน้ำ! การแข่งขันจะเริ่มทันทีหลังจากจบโฆษณา!"
L35_1.m_Talk_THA = L36_1
L36_1 = "Ai muốn đi vệ sinh thì đây là cơ hội cuối cùng đấy! Trận đấu sẽ bắt đầu ngay sau quảng cáo!"
L35_1.m_Talk_VTN = L36_1
L36_1 = "现在就是去卫生间的最好的时机！广告之后比赛马上开始~？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Das ist eure letzte Chance, auf die Toilette zu gehen! Das Spiel beginnt direkt nach der Werbepause!"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Bon ! C'est votre dernière chance de passer aux toilettes ! Le match commence... Juste après la pub !"
L35_1.m_Talk_FRA = L36_1
